llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C39"],
      "claim": "EM574, a macrolide derivative, has an estimated human oral bioavailability of about 2% based on oral clearance far exceeding hepatic blood flow; this is the strongest structurally relevant anchor and supports low F for the query macrolide.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Cefditoren has an absolute oral bioavailability of approximately 14% under fasting conditions, below the 20% threshold, supporting low F for a high-molecular-weight, ionizable, sugar-containing molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "YH4808 has a low absolute oral bioavailability of 10.1% with high variability, supporting low F for a molecule with substantial polarity and ionization.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "A related large glycosylated natural product showed low oral bioavailability relative to assay quantification limits, supporting low F for a large glycoside-like scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Oseltamivir has high oral bioavailability of about 79%, but it is a small ester prodrug with different absorption characteristics; this contradictory evidence is less transferable to the large, ionizable macrolide query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C34"],
      "claim": "Etoposide shows oral bioavailability of 25-75% in patients, above the threshold, but with high variability and a lower transfer score; it provides limited contradictory evidence for a glycoside.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of high-transfer experimental evidence, especially the macrolide EM574 with ~2% F, plus cefditoren and YH4808 below 20%, supports low oral bioavailability; high-F comparators are less transferable or highly variable.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability data for the exact query molecule.",
    "Acid-labile acetal stability and first-pass metabolism of the query are not directly measured.",
    "High-F macrolides such as clarithromycin or azithromycin are not represented in the provided evidence set."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

